// src/pages/AdminLocalesPage.js
import React, { useEffect, useState } from 'react';
import { BACKEND_URL } from '../services/api';

export default function AdminLocalesPage() {
  // Lista de locales cargados
  const [locales, setLocales] = useState([]);
  // Paginación
  const [page, setPage] = useState(0);
  const LIMIT = 10;

  // Campo para crear un local nuevo
  const [newLocalName, setNewLocalName] = useState('');

  // Modo edición: si editingLocal es null, estamos creando; si tiene datos, lo editamos
  const [editingLocal, setEditingLocal] = useState(null);
  const [editLocalName, setEditLocalName] = useState('');

  useEffect(() => {
    loadLocales();
    // eslint-disable-next-line
  }, [page]);

  // Función que carga locales desde la API
  async function loadLocales() {
    try {
      const offset = page * LIMIT;
      const resp = await fetch(
        `${BACKEND_URL}/locals?limit=${LIMIT}&offset=${offset}&order=name:asc`
      );
      const data = await resp.json();

      // Si la respuesta no es un array, se imprime el error y se asigna una lista vacía
      if (!Array.isArray(data)) {
        console.error('Respuesta de la API no es lista de locales:', data);
        setLocales([]);
        return;
      }

      // Si la página actual está vacía y no es la página cero, retrocede una
      if (data.length === 0 && page > 0) {
        setPage(page - 1);
        return;
      }
      setLocales(data);
    } catch (error) {
      console.error('Error al cargar locales:', error);
      alert('No se pudieron cargar los locales.');
    }
  }

  // Crear un nuevo local
  async function handleCreate(e) {
    e.preventDefault();
    if (!newLocalName.trim()) {
      alert('Debe ingresar un nombre para el local');
      return;
    }
    try {
      await fetch(`${BACKEND_URL}/locals`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: newLocalName }),
      });
      setNewLocalName('');
      loadLocales();
    } catch (error) {
      console.error('Error al crear local:', error);
      alert('No se pudo crear el local.');
    }
  }

  // Borrar un local
  async function handleDelete(id) {
    if (!window.confirm('¿Está seguro de eliminar este local?')) return;
    try {
      await fetch(`${BACKEND_URL}/locals/${id}`, {
        method: 'DELETE',
      });
      loadLocales();
    } catch (error) {
      console.error('Error al eliminar local:', error);
      alert('No se pudo eliminar el local.');
    }
  }

  // Iniciar el modo edición para un local
  function startEditing(local) {
    setEditingLocal(local);
    setEditLocalName(local.name);
  }

  // Guardar cambios de la edición
  async function handleUpdate(e) {
    e.preventDefault();
    if (!editLocalName.trim()) {
      alert('El nombre del local no puede estar vacío');
      return;
    }
    try {
      await fetch(`${BACKEND_URL}/locals/${editingLocal.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: editLocalName }),
      });
      setEditingLocal(null);
      setEditLocalName('');
      loadLocales();
    } catch (error) {
      console.error('Error al actualizar local:', error);
      alert('No se pudo actualizar el local.');
    }
  }

  // Cancelar la edición
  function cancelEdit() {
    setEditingLocal(null);
    setEditLocalName('');
  }

  // Paginación
  function goPrev() {
    setPage(Math.max(0, page - 1));
  }
  function goNext() {
    setPage(page + 1);
  }

  return (
    <div>
      <h3>
        <i className="fa-solid fa-store"></i> Gestión de Locales
      </h3>

      {/* Formulario para crear un nuevo local */}
      {!editingLocal && (
        <form onSubmit={handleCreate} className="mb-4">
          <div className="form-group">
            <label>Nombre del Local</label>
            <input
              type="text"
              className="form-control"
              value={newLocalName}
              onChange={(e) => setNewLocalName(e.target.value)}
              required
            />
          </div>
          <button type="submit" className="btn btn-success btn-custom">
            Agregar Local
          </button>
        </form>
      )}

      {/* Formulario para editar un local */}
      {editingLocal && (
        <form onSubmit={handleUpdate} className="mb-4">
          <div className="form-group">
            <label>Editando Local (ID: {editingLocal.id})</label>
            <input
              type="text"
              className="form-control"
              value={editLocalName}
              onChange={(e) => setEditLocalName(e.target.value)}
              required
            />
          </div>
          <button type="submit" className="btn btn-primary btn-custom">
            Guardar Cambios
          </button>
          <button
            type="button"
            className="btn btn-secondary ml-2"
            onClick={cancelEdit}
          >
            Cancelar
          </button>
        </form>
      )}

      <table className="table table-bordered">
        <thead>
          <tr>
            <th>ID</th>
            <th>Nombre</th>
            <th style={{ width: '150px' }}>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {locales.map((loc) => (
            <tr key={loc.id}>
              <td>{loc.id}</td>
              <td>{loc.name}</td>
              <td>
                <button
                  className="btn btn-info btn-sm mr-2"
                  onClick={() => startEditing(loc)}
                >
                  <i className="fa-solid fa-pen-to-square"></i> Editar
                </button>
                <button
                  className="btn btn-danger btn-sm"
                  onClick={() => handleDelete(loc.id)}
                >
                  <i className="fa-solid fa-trash"></i> Borrar
                </button>
              </td>
            </tr>
          ))}
          {locales.length === 0 && (
            <tr>
              <td colSpan={3}>No hay locales</td>
            </tr>
          )}
        </tbody>
      </table>

      <div className="d-flex justify-content-between">
        <button
          className="btn btn-secondary btn-sm"
          onClick={goPrev}
          disabled={page === 0}
        >
          Anterior
        </button>
        <button
          className="btn btn-secondary btn-sm"
          onClick={goNext}
          disabled={locales.length < LIMIT}
        >
          Siguiente
        </button>
      </div>
    </div>
  );
}
